import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listDirectMessagesHandler } from "../handlers/listDirectMessagesHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof listDirectMessagesHandler>>;

export function useListDirectMessages(
  teamPk: TeamPartition,
  subTeamId: string,
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listDirectMessages", teamPk, subTeamId, bookmark],
    queryFn: () => listDirectMessagesHandler(teamPk, subTeamId, bookmark),
    ...options,
  });
}
